["The window"] = "窗口",
["The window above the bar holds"] = "条上方的窗口容纳",
["The windows no longer move when dragged."] = "拖动时窗口不再移动。",
["The word"] = "该词",
["The wording of each message. %a = amount, %s = spell, %n = name, %t = kind. Empty = the original."] = "每条消息的措辞。%a = 数值,%s = 法术,%n = 名字,%t = 种类。留空 = 原样。",
