["Thin ring"] = "细环",
["Thirdparty: Integrations"] = "第三方:集成",
["This character takes the picked profile's settings (reloads)."] = "此角色采用所选配置文件的设置(会重载)。",
["This frame's own colours (off = the ones on General)."] = "此框体自己的颜色(关闭 = 使用常规页中的)。",
["This layout keeps its own spells, items and macros on the action bars: what you put there while in it comes back when you switch to it. (A talent spec with its own spells keeps them per layout instead.)"] = "此布局在动作条上保留自己的法术、物品和宏:你在其中放置的内容会在切换回来时恢复。(带有自己法术的天赋方案则改为按布局保存。)",
["This set"] = "此套装",
["This window's look"] = "此窗口的外观",
["Thistle Tea"] = "蓟草茶",
["Thousands separators"] = "千位分隔符",
["Threat"] = "仇恨",
["Threat and colours"] = "仇恨和颜色",
["Threat meter"] = "仇恨统计",
["Three texts on the health bar and three on the power bar. Pick one with the tabs, or click it in the preview."] = "生命条上三段文字,能量条上三段文字。用标签选择一个,或在预览中点击。",
["Ticked: the game's own frames for that part. The same switches sit at the top of each part's page."] = "勾选:该部分使用游戏自带框体。相同的开关位于各部分页面顶部。",
["Ticks of DoTs too - busy with several warlocks or priests."] = "持续伤害的每一跳也计算 - 多名术士或牧师时会很繁忙。",
