-- a text of several lines is also kept line by line (the string list of tests lists lines)
local extra = {}
for k, v in pairs(words) do
  if string.find(k, "\n", 1, true) then
    local a, b, pos1, pos2 = {}, {}, 1, 1
    while true do
      local e1 = string.find(k, "\n", pos1, true)
      table.insert(a, string.sub(k, pos1, (e1 or 0) - 1 + (e1 and 0 or string.len(k) + 1)))
      if not e1 then break end
      pos1 = e1 + 1
    end
    while true do
      local e2 = string.find(v, "\n", pos2, true)
      table.insert(b, string.sub(v, pos2, (e2 or 0) - 1 + (e2 and 0 or string.len(v) + 1)))
      if not e2 then break end
      pos2 = e2 + 1
    end
    if table.getn(a) == table.getn(b) then
      for i = 1, table.getn(a) do
        if a[i] ~= "" and extra[a[i]] == nil then extra[a[i]] = b[i] end
      end
    end
  end
end
for k, v in pairs(extra) do if words[k] == nil then words[k] = v end end
for k, v in pairs(words) do if rawget(T, k) == nil then T[k] = v end end
